a.concept(0,'common_library_gate','Common computational capability library','Owner-selected prerequisite deliverable before remaining 5.0 release work resumes, with exact capabilities and production consumers bound by T-287 delivery contract.')
a.constraint(0,'consolidation_correctness',['release_scope'],'5.0 must have no more reachable semantic authorities, registries, ledgers, stores, runtimes, controllers or materially equivalent algorithm realizations than the conserved 4.6 foundation. Delete new authority duplication before release. Inherited/new redundancy affecting admission, identity, currentness, replay or fresh-process behavior is a nondeferrable correctness defect.')
a.constraint(0,'library_acceptance_before_release_work',['common_library_gate'],'Delivery requires accepted design, usable implementations actually consumed by selected production paths, duplicate-responsibility retirement or justified retention, executed obligations, independent assessment and recorded acceptance. Design acceptance alone is insufficient. Bounded integration/installed proof is library work; general release integration/lifecycle/qualification/publication waits for its acceptance. No new feature family/runtime/authority/separately published package is created; remaining qualification/human release acceptance still applies.')
a.latitude(0,'successor_pure_compression',['release_scope'],['Outside the selected library deliverable, after correctness/authority conditions hold, contract equivalent pure helpers, internal validator placement, harness mechanics, caches or module layout as 5.1 realization compression.'],['Treating that optional successor compression as a fixed-5.0 capability gate or authorization for a compatibility path/rival truth source.','Restoring reserved F08/F12 or human-response obligations through renumbering, counts or lower-level wording.'])
features=[
('A5-F01','exact_product','Exact Product/install/workspace/catalog','Source-blind consumers resolve, verify, install and bind exact artifacts, then deterministically construct one exact GraphFunction catalog from supplied published GTL with typed conflict and dependency handling.'),
('A5-F02','complete_language','Complete GTL authoring/validation','Typed TypeScript, raw admission, canonical serialization, whole-Program validation, module publication and malformed refusal cover the complete retained language.'),
('A5-F03','complete_traversal','Complete graph/C/traversal execution','HoG traverses every retained graph relation, all seven C constructors and complete 4.6 conservation matrix without lowering/special runners; each C call retains locus, fibre, evidence, admitted result, judgment, parent/child relation, conservation basis and lawful join.'),
('A5-F04','fp_integrity','Probabilistic result integrity','Every F_P call receives declared instructions/contracts; malformed, incomplete, contradictory or unattributed output refuses before effect or closure.'),
('A5-F05','public_authority','One Public contract authority','Catalog, SDK, CLI, schemas, capability projections, handlers and documentation derive from one typed definition and agree exactly at release.'),
('A5-F06','thin_public_shells','Thin SDK/CLI','Native consumers inspect, validate, publish, invoke, start, read, continue admitted automatic work and inspect truthful blocks without adapter control; native human response/resume remains 5.1.'),
('A5-F07','system_loop','Complete One Surface','Program orders synthesizeModel/evalGap/evaluateNext/evaluateAction as four distinct semantic authorities; ABG owns surrounding intent/invocation/evidence/continuation boundaries. New evidence refreshes model, gap, next action and action-result truth before next step.'),
('A5-F09','catalog_semantics','Catalog semantics','Inspect/purely narrow the one reconstructible catalog, deterministically apply noncallable declarations, invoke only exact published GraphFunctions and start only exact published Programs.'),
('A5-F10','event_truth','Event-sourced runtime truth','Invocation, results, evidence, consequences, correction, retry, child traversal, conserved yield/human hold/escalation/continuation, failure/block/non-admission/closure/workspace transformation and projections remain one causal episode under release allocation. One transition authority resolves competing pressure; replay, not caller memory, derives result/state/change explanation.'),
('A5-F11','self_conformance','Self-conformance','Exact candidate evaluates all applicable specification, design, contract, realization, proof, qualification and release obligations without exemption or self-minted assurance.'),
('A5-F13','native_independence','Native independence','SDK/CLI operates without marketplace host; retained adapters delegate the same Public contract without copied semantics. Additional host work/mandatory parity qualify in 5.1.'),
('A5-F14','installed_mechanics','Installed mechanics proof','Clean source-blind install executes an independently authored minimal deterministic program and live F_P path with typed results/evidence/events/replay; external test program owns declarations, contracts, leaf binding and oracle.'),
('A5-F15','exact_qualification','Exact-candidate qualification','One content-addressed qualification family separates pre_rc_candidate from installed_rc; binds exact QualificationLawBasis, authenticated self-conformance, complete behavioral coverage, prospective RC authorization and non-bypassed installed-RC verdict. Changed qualifying subject requires higher RC/applicable gates; acceptance creates no third subject.'),
('A5-F16','immutable_release','Immutable RC and accepted release','Qualified pre-RC authorizes one immutable RC; exact installed RC qualifies; actual human Product authority accepts/withholds that same unchanged RC. Tag/package/manifest/checksums/post-publication install identify Product. Latest-published-RC selector advances independently of acceptance/adoption; acceptance creates no second cut, rename or replacement package.'),
('A5-F17','downstream_lifecycle','Specification-driven downstream lifecycle','Prospectively selected real source progresses through Intent/Product, Requirements, Design, working behavior, admitted evidence and consequential targeted revision using installed Public contracts only. Preserve original/selected/excluded/new obligations and residuals; satisfy every mandatory selected outcome without local runtime/controller. S06 qualifies this contract class; original Data Mapper and complete downstream delivery stay independently owned.')]
for ident,key,label,meaning in features:
    quote=next(line for line in a.sections[0]['text'].splitlines() if line.startswith(f'| `{ident}` |'))
    g=(0,quote)
    a.concept(g,key,label,f'{ident}: selected Product outcome, not an implementation module or operation count.')
    a.constraint(g,key+'_obligation',[key],meaning)
    a.relation(g,'scope_requires_'+key,'release_scope',key,'requires','This named outcome is mandatory within its owning release applicability.',True)
